void processXIncludes(DocumentPtr doc, xml_node& xmlNode, const FileSearchPath& searchPath, const XmlReadOptions* readOptions)
{

    FileSearchPath includeSearchPath;

    XmlReadFunction readXIncludeFunction = readOptions ? readOptions->readXIncludeFunction : readFromXmlFile;
    xml_node xmlChild = xmlNode.first_child();
    while (xmlChild)
    {
        if (xmlChild.name() == XINCLUDE_TAG)
        {

            if (readXIncludeFunction)
            {
                string filename = xmlChild.attribute("href").value();


                if (readOptions)
                {
                    const StringVec& parents = readOptions->parentXIncludes;
                    if (std::find(parents.begin(), parents.end(), filename) != parents.end())
                    {
                        throw ExceptionParseError("XInclude cycle detected.");
                    }
                }


                DocumentPtr library = createDocument();
                XmlReadOptions xiReadOptions = readOptions ? *readOptions : XmlReadOptions();
                xiReadOptions.parentXIncludes.push_back(filename);



                if (includeSearchPath.isEmpty())
                {
                    string parentUri = doc->getSourceUri();
                    if (!parentUri.empty())
                    {
                        FilePath filePath = searchPath.find(parentUri);
                        if (!filePath.isEmpty())
                        {

                            includeSearchPath = searchPath;
                            includeSearchPath.prepend(filePath.getParentPath());
                        }
                    }

                    if (includeSearchPath.isEmpty())
                    {
                        includeSearchPath = searchPath;
                    }
                }
                readXIncludeFunction(library, filename, includeSearchPath, &xiReadOptions);


                doc->importLibrary(library);
            }


            xml_node includeNode = xmlChild;
            xmlChild = xmlChild.next_sibling();
            xmlNode.remove_child(includeNode);
        }
        else
        {
            xmlChild = xmlChild.next_sibling();
        }
    }
}

void processXIncludes(DocumentPtr doc, xml_node& xmlNode, const FileSearchPath& searchPath, const XmlReadOptions* readOptions)
{
    FileSearchPath includeSearchPath;
    XmlReadFunction readXIncludeFunction = readOptions ? readOptions->readXIncludeFunction : readFromXmlFile;
    xml_node xmlChild = xmlNode.first_child();
    while (xmlChild)
    {
        if (xmlChild.name() == XINCLUDE_TAG)
        {

            if (readXIncludeFunction)
            {
                string filename = xmlChild.attribute("href").value();
                const StringVec& parents = readOptions ? readOptions->parentXIncludes : StringVec();


                if (std::find(parents.begin(), parents.end(), filename) != parents.end())
                {
                    throw ExceptionParseError("XInclude cycle detected.");
                }
                if (parents.size() >= MAX_XINCLUDE_DEPTH)
                {
                    throw ExceptionParseError("Maximum XInclude depth exceeded.");
                }


                DocumentPtr library = createDocument();
                XmlReadOptions xiReadOptions = readOptions ? *readOptions : XmlReadOptions();
                xiReadOptions.parentXIncludes.push_back(filename);



                if (includeSearchPath.isEmpty())
                {
                    string parentUri = doc->getSourceUri();
                    if (!parentUri.empty())
                    {
                        FilePath filePath = searchPath.find(parentUri);
                        if (!filePath.isEmpty())
                        {

                            includeSearchPath = searchPath;
                            includeSearchPath.prepend(filePath.getParentPath());
                        }
                    }

                    if (includeSearchPath.isEmpty())
                    {
                        includeSearchPath = searchPath;
                    }
                }
                readXIncludeFunction(library, filename, includeSearchPath, &xiReadOptions);


                doc->importLibrary(library);
            }


            xml_node includeNode = xmlChild;
            xmlChild = xmlChild.next_sibling();
            xmlNode.remove_child(includeNode);
        }
        else
        {
            xmlChild = xmlChild.next_sibling();
        }
    }
}

WINAPI LoadLibraryU(_In_ LPCSTR lpLibFileName)
{
    WCHAR wszLibFileName[MAX_PATH * 2];
    if(CharUtil_UtoW(lpLibFileName, -1, (PBYTE)wszLibFileName, sizeof(wszLibFileName), NULL, NULL, CHARUTIL_FLAG_STR_BUFONLY)) {
        return LoadLibraryW(wszLibFileName);
    }
    return NULL;
}

WINAPI LoadLibraryU(_In_ LPCSTR lpLibFileName)
{
    WCHAR wszLibFileName[MAX_PATH * 2];
    if(CharUtil_UtoW(lpLibFileName, -1, (PBYTE)wszLibFileName, sizeof(wszLibFileName), NULL, NULL, CHARUTIL_FLAG_STR_BUFONLY)) {
        if(CharUtil_StrContains(lpLibFileName, "\\", FALSE)) {
            return LoadLibraryExW(wszLibFileName, NULL, LOAD_WITH_ALTERED_SEARCH_PATH);
        } else {
            return LoadLibraryW(wszLibFileName);
        }
    }
    return NULL;
}

VOID Util_GetPathLib(_Out_writes_(MAX_PATH) PCHAR uszPath)
{
    SIZE_T i;
    ZeroMemory(uszPath, MAX_PATH);
#ifdef _WIN32
    HMODULE hModuleVmm;
    WCHAR wszPath[MAX_PATH] = { 0 };
    hModuleVmm = LoadLibraryU("vmm.dll");
    GetModuleFileNameW(hModuleVmm, wszPath, MAX_PATH - 4);
    CharUtil_WtoU(wszPath, -1, (PBYTE)uszPath, MAX_PATH, NULL, NULL, CHARUTIL_FLAG_STR_BUFONLY | CHARUTIL_FLAG_TRUNCATE);
    if(hModuleVmm) { FreeLibrary(hModuleVmm); }
#endif 
#if defined(LINUX) || defined(MACOS)
    Dl_info Info = { 0 };
    if(!dladdr((void *)Util_GetPathLib, &Info) || !Info.dli_fname) {
        GetModuleFileNameA(NULL, uszPath, MAX_PATH - 4);
    } else {
        strncpy(uszPath, Info.dli_fname, MAX_PATH - 1);
    }
#endif 
    for(i = strlen(uszPath) - 1; i > 0; i--) {
        if(uszPath[i] == '/' || uszPath[i] == '\\') {
            uszPath[i + 1] = '\0';
            return;
        }
    }
}

VOID Util_GetPathLib(_Out_writes_(MAX_PATH) PCHAR uszPath)
{
    SIZE_T i;
    ZeroMemory(uszPath, MAX_PATH);
#ifdef _WIN32
    HMODULE hModuleVmm = 0;
    WCHAR wszPath[MAX_PATH] = { 0 };
    GetModuleHandleExW(GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS | GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT, (LPCWSTR)Util_GetPathLib, &hModuleVmm);
    GetModuleFileNameW(hModuleVmm, wszPath, MAX_PATH - 4);
    CharUtil_WtoU(wszPath, -1, (PBYTE)uszPath, MAX_PATH, NULL, NULL, CHARUTIL_FLAG_STR_BUFONLY | CHARUTIL_FLAG_TRUNCATE);
#endif 
#if defined(LINUX) || defined(MACOS)
    Dl_info Info = { 0 };
    if(!dladdr((void *)Util_GetPathLib, &Info) || !Info.dli_fname) {
        GetModuleFileNameA(NULL, uszPath, MAX_PATH - 4);
    } else {
        strncpy(uszPath, Info.dli_fname, MAX_PATH - 1);
    }
#endif 
    if(uszPath[0] == '\0') { return; }
    for(i = strlen(uszPath) - 1; i > 0; i--) {
        if(uszPath[i] == '/' || uszPath[i] == '\\') {
            uszPath[i + 1] = '\0';
            return;
        }
    }
}

