static void rfapiRibBi2Ri(struct bgp_path_info *bpi, struct rfapi_info *ri,
			  uint32_t lifetime)
{
	struct bgp_attr_encap_subtlv *pEncap;

	ri->cost = rfapiRfpCost(bpi->attr);
	ri->lifetime = lifetime;


	for (pEncap = bgp_attr_get_vnc_subtlvs(bpi->attr); pEncap;
	     pEncap = pEncap->next) {
		struct bgp_tea_options *hop;

		switch (pEncap->type) {
		case BGP_VNC_SUBTLV_TYPE_LIFETIME:

			break;

		case BGP_VNC_SUBTLV_TYPE_RFPOPTION:
			hop = XCALLOC(MTYPE_BGP_TEA_OPTIONS,
				      sizeof(struct bgp_tea_options));
			assert(hop);
			hop->type = pEncap->value[0];
			hop->length = pEncap->value[1];
			hop->value = XCALLOC(MTYPE_BGP_TEA_OPTIONS_VALUE,
					     pEncap->length - 2);
			assert(hop->value);
			memcpy(hop->value, pEncap->value + 2,
			       pEncap->length - 2);
			if (hop->length > pEncap->length - 2) {
				zlog_warn(
					"%s: VNC subtlv length mismatch: RFP option says %d, attr says %d (shrinking)",
					__func__, hop->length,
					pEncap->length - 2);
				hop->length = pEncap->length - 2;
			}
			hop->next = ri->tea_options;
			ri->tea_options = hop;
			break;

		default:
			break;
		}
	}

	rfapi_un_options_free(ri->un_options); 
	ri->un_options = rfapi_encap_tlv_to_un_option(bpi->attr);




	if (bpi->extra && decode_rd_type(bpi->extra->vnc->vnc.import.rd.val) ==
				  RD_TYPE_VNC_ETH) {


		struct rfapi_vn_option *vo;

		vo = XCALLOC(MTYPE_RFAPI_VN_OPTION,
			     sizeof(struct rfapi_vn_option));
		assert(vo);

		vo->type = RFAPI_VN_OPTION_TYPE_L2ADDR;



		memcpy(&vo->v.l2addr.macaddr,
		       bpi->extra->vnc->vnc.import.rd.val + 2, ETH_ALEN);

		(void)rfapiEcommunityGetLNI(bgp_attr_get_ecommunity(bpi->attr),
					    &vo->v.l2addr.logical_net_id);
		(void)rfapiEcommunityGetEthernetTag(
			bgp_attr_get_ecommunity(bpi->attr),
			&vo->v.l2addr.tag_id);


		vo->v.l2addr.local_nve_id =
			bpi->extra->vnc->vnc.import.rd.val[1];


		vo->v.l2addr.label =
			BGP_PATH_INFO_NUM_LABELS(bpi)
				? decode_label(&bpi->extra->labels->label[0])
				: MPLS_INVALID_LABEL;

		rfapi_vn_options_free(
			ri->vn_options); 
		ri->vn_options = vo;
	}




	if (bpi->extra && bpi->extra->vnc->vnc.import.aux_prefix.family) {
		ri->rk.aux_prefix = bpi->extra->vnc->vnc.import.aux_prefix;
	}
}

static void rfapiRibBi2Ri(struct bgp_path_info *bpi, struct rfapi_info *ri,
			  uint32_t lifetime)
{
	struct bgp_attr_encap_subtlv *pEncap;

	ri->cost = rfapiRfpCost(bpi->attr);
	ri->lifetime = lifetime;


	for (pEncap = bgp_attr_get_vnc_subtlvs(bpi->attr); pEncap;
	     pEncap = pEncap->next) {
		struct bgp_tea_options *hop;

		switch (pEncap->type) {
		case BGP_VNC_SUBTLV_TYPE_LIFETIME:

			break;

		case BGP_VNC_SUBTLV_TYPE_RFPOPTION:

			if (pEncap->length < 3)
				break;


			if (pEncap->value[1] == 0)
				break;

			hop = XCALLOC(MTYPE_BGP_TEA_OPTIONS,
				      sizeof(struct bgp_tea_options));
			assert(hop);
			hop->type = pEncap->value[0];
			hop->length = pEncap->value[1];

			hop->value = XCALLOC(MTYPE_BGP_TEA_OPTIONS_VALUE,
					     pEncap->length - 2);
			assert(hop->value);
			memcpy(hop->value, pEncap->value + 2,
			       pEncap->length - 2);
			if (hop->length > pEncap->length - 2) {
				zlog_warn(
					"%s: VNC subtlv length mismatch: RFP option says %d, attr says %d (shrinking)",
					__func__, hop->length,
					pEncap->length - 2);
				hop->length = pEncap->length - 2;
			}
			hop->next = ri->tea_options;
			ri->tea_options = hop;
			break;

		default:
			break;
		}
	}

	rfapi_un_options_free(ri->un_options); 
	ri->un_options = rfapi_encap_tlv_to_un_option(bpi->attr);




	if (bpi->extra && decode_rd_type(bpi->extra->vnc->vnc.import.rd.val) ==
				  RD_TYPE_VNC_ETH) {


		struct rfapi_vn_option *vo;

		vo = XCALLOC(MTYPE_RFAPI_VN_OPTION,
			     sizeof(struct rfapi_vn_option));
		assert(vo);

		vo->type = RFAPI_VN_OPTION_TYPE_L2ADDR;



		memcpy(&vo->v.l2addr.macaddr,
		       bpi->extra->vnc->vnc.import.rd.val + 2, ETH_ALEN);

		(void)rfapiEcommunityGetLNI(bgp_attr_get_ecommunity(bpi->attr),
					    &vo->v.l2addr.logical_net_id);
		(void)rfapiEcommunityGetEthernetTag(
			bgp_attr_get_ecommunity(bpi->attr),
			&vo->v.l2addr.tag_id);


		vo->v.l2addr.local_nve_id =
			bpi->extra->vnc->vnc.import.rd.val[1];


		vo->v.l2addr.label =
			BGP_PATH_INFO_NUM_LABELS(bpi)
				? decode_label(&bpi->extra->labels->label[0])
				: MPLS_INVALID_LABEL;

		rfapi_vn_options_free(
			ri->vn_options); 
		ri->vn_options = vo;
	}




	if (bpi->extra && bpi->extra->vnc->vnc.import.aux_prefix.family) {
		ri->rk.aux_prefix = bpi->extra->vnc->vnc.import.aux_prefix;
	}
}

int bgp_flowspec_bitmask_decode(enum bgp_flowspec_util_nlri_t type,
				 uint8_t *nlri_ptr,
				 uint32_t max_len,
				 void *result, int *error)
{
	int op[8];
	int len, value_size, loop = 0, value;
	char *ptr = (char *)result; 
	struct bgp_pbr_match_val *mval = (struct bgp_pbr_match_val *)result;
	uint32_t offset = 0;
	int len_string = BGP_FLOWSPEC_STRING_DISPLAY_MAX;
	int len_written;

	*error = 0;


	if (max_len < 1) {
		*error = -1;
		return 0;
	}

	do {
		if (loop > BGP_PBR_MATCH_VAL_MAX) {
			*error = -2;
			return offset;
		}

		hex2bin(&nlri_ptr[offset], op);

		if (op[1] == 1 && loop == 0)
			*error = -1;
		offset++;
		len = 2 * op[2] + op[3];
		value_size = 1 << len;

		if (offset > max_len || (uint32_t)value_size > (max_len - offset)) {
			*error = -1;
			break;
		}

		value = hexstr2num(&nlri_ptr[offset], value_size);
		switch (type) {
		case BGP_FLOWSPEC_RETURN_STRING:
			if (op[1] == 1 && loop != 0) {
				len_written = snprintf(ptr, len_string,
						       ",&");
				len_string -= len_written;
				ptr += len_written;
			} else if (op[1] == 0 && loop != 0) {
				len_written = snprintf(ptr, len_string,
						      ",|");
				len_string -= len_written;
				ptr += len_written;
			}
			if (op[7] == 1) {
				len_written = snprintf(ptr, len_string,
					       "= ");
				len_string -= len_written;
				ptr += len_written;
			} else {
				len_written = snprintf(ptr, len_string,
						       "∋ ");
				len_string -= len_written;
				ptr += len_written;
			}
			if (op[6] == 1) {
				len_written = snprintf(ptr, len_string,
					       "! ");
				len_string -= len_written;
				ptr += len_written;
			}
			len_written = snprintf(ptr, len_string,
				       "%d", value);
			len_string -= len_written;
			ptr += len_written;
			break;
		case BGP_FLOWSPEC_CONVERT_TO_NON_OPAQUE:

			if (*error == -2)
				break;
			mval->value = value;
			if (op[6] == 1) {

				SET_FLAG(mval->compare_operator,
					 OPERATOR_COMPARE_LESS_THAN);
				SET_FLAG(mval->compare_operator,
					 OPERATOR_COMPARE_GREATER_THAN);
			} else
				SET_FLAG(mval->compare_operator,
					 OPERATOR_COMPARE_EQUAL_TO);
			if (op[7] == 1)
				SET_FLAG(mval->compare_operator,
					 OPERATOR_COMPARE_EXACT_MATCH);
			if (op[1] == 1)
				mval->unary_operator =
					OPERATOR_UNARY_AND;
			else
				mval->unary_operator =
					OPERATOR_UNARY_OR;
			mval++;
			break;
		case BGP_FLOWSPEC_VALIDATE_ONLY:
		case BGP_FLOWSPEC_RETURN_JSON:

			break;
		}
		offset += value_size;
		loop++;
	} while (op[0] == 0 && offset < max_len - 1);
	if (offset > max_len)
		*error = -1;

	if (*error == 0)
		*error = loop;
	return offset;
}

