			    || TLV_BODY_SIZE(tlvh) > ALGORITHM_COUNT)
				break;
			algo = (struct ri_sr_tlv_sr_algorithm *)tlvh;

			for (int i = 0; i < ntohs(algo->header.length); i++) {
