		    VSread(vdataID, (uint8 *) buf, 1, FULL_INTERLACE);


		    for (i = 0, j = 0; i < fsize; i++)
		    {
			j += buf[i];
		    }





		    if (j == 255 * fsize)
		    {
			dims[0] = 0;
		    }

		    free(buf);
		}

		VSdetach(vdataID);
	    }
	    else
	    {

		status = SWSDfldsrch(swathID, sdInterfaceID, fieldname,
				     &dum, &dum, &dum, &dum, dims,
				     &dum);
	    }
	}
    }
    free(metabuf);

    if (*rank == -1)
    {
	status = -1;
    }
    free(utlstr);

    return (status);
}

