static size_t header_cb(char *buf, size_t size, size_t nmemb, void *ctx)
{
	size_t total_size = size * nmemb;
	struct jwks_data *data = ctx;

	if (strncasecmp(buf, "Content-Length:", 15))
		return total_size;

	data->alloc_size = (size_t)atol(buf + 15);
	data->buf = jwt_malloc(data->alloc_size + 1);
	if (!data->buf)
		return 0; 

	data->size = 0;
	data->buf[0] = '\0';

	return total_size;
}

static size_t header_cb(char *buf, size_t size, size_t nmemb, void *ctx)
{
	size_t total_size = size * nmemb;
	struct jwks_data *data = ctx;
	long content_length;
	char *endptr;

	if (strncasecmp(buf, "Content-Length:", 15))
		return total_size;

	content_length = strtol(buf + 15, &endptr, 10);
	if (endptr == buf + 15 || content_length <= 0 ||
	    content_length > JWKS_MAX_RESPONSE_SIZE)
		return 0;

	data->alloc_size = (size_t)content_length;
	data->buf = jwt_malloc(data->alloc_size + 1);
	if (!data->buf)
		return 0; 

	data->size = 0;
	data->buf[0] = '\0';

	return total_size;
}

const jwk_item_t *jwks_item_get(const jwk_set_t *jwk_set, size_t index)
{
	jwk_item_t *item = NULL;
	size_t i = 0;

	list_for_each_entry(item, &jwk_set->head, node) {
		if (i == index)
			return item;
		i++;
	}

	return NULL;
}

const jwk_item_t *jwks_item_get(const jwk_set_t *jwk_set, size_t index)
{
	jwk_item_t *item = NULL;
	size_t i = 0;

	if (jwk_set == NULL)
		return NULL;

	list_for_each_entry(item, &jwk_set->head, node) {
		if (i == index)
			return item;
		i++;
	}

	return NULL;
}

jwt_common_t *FUNC(new)(void)
{
	jwt_common_t *__cmd = jwt_malloc(sizeof(*__cmd));

	if (__cmd == NULL)
		return NULL; 

	memset(__cmd, 0, sizeof(*__cmd));

	__cmd->c.payload = jwt_json_create();
	__cmd->c.headers = jwt_json_create();
	__cmd->c.claims = CLAIMS_DEF;

	if (!__cmd->c.payload || !__cmd->c.headers)
		jwt_freemem(__cmd); 

	return __cmd;
}

jwt_common_t *FUNC(new)(void)
{
	jwt_common_t *__cmd = jwt_malloc(sizeof(*__cmd));

	if (__cmd == NULL)
		return NULL; 

	memset(__cmd, 0, sizeof(*__cmd));

	__cmd->c.payload = jwt_json_create();
	__cmd->c.headers = jwt_json_create();
	__cmd->c.claims = CLAIMS_DEF;

	if (!__cmd->c.payload || !__cmd->c.headers) {

		jwt_json_release(__cmd->c.payload);
		jwt_json_release(__cmd->c.headers);
		jwt_freemem(__cmd);

	}

	return __cmd;
}

JWT_CONSTRUCTOR
void jwt_init()
{
	const char *opname = getenv("JWT_CRYPTO");


	if (opname == NULL || opname[0] == '\0') {
		jwt_ops = jwt_ops_available[0];
		return;
	}


	if (jwt_set_crypto_ops(opname)) {
		jwt_ops = jwt_ops_available[0];
		fprintf(stderr, "LibJWT: No such crypto ops [%s], falling back to [%s]\n",
			opname, jwt_ops->name);
	}
}

