    luaD_hook(L, LUA_HOOKRET, -1, ftransfer, nres);  
    ci->func -= delta;
  }
  if (isLua(ci = ci->previous))
    L->oldpc = pcRel(ci->u.l.savedpc, ci_func(ci)->p);  
  return restorestack(L, oldtop);
}

