    string MolFormula=_pmol->GetFormula();











    atoms.clear();
    return false;
  }















  return true;
}

string transform3d::DescribeAsString() const
    {
      ostringstream r;
      int n, i, j;
      const matrix3x3 *m = static_cast <const matrix3x3 *> (this);
      const vector3 *v = static_cast <const vector3 *> (this);
      bool neg, first;
      for (i = 0; i < 3; i++)
        {
          if (i)
            r << ",";
          n = static_cast<int> (floor((*v)[i] * 12.0 + 0.1));
          j = 0;
          while ((*m)(i, j) == 0.)
            j++;
          neg = (*m)(i, j) < 0.;
          switch (n)
            {
              case 2:
                r << ((neg)? "1/6": "1/6+");
                break;
              case 3:
                r << ((neg)? "1/4": "1/4+");
                break;
              case 4:
                r << ((neg)? "1/3": "1/3+");
                break;
              case 6:
                r << ((neg)? "1/2": "1/2+");
                break;
              case 8:
                r << ((neg)? "2/3": "2/3+");
                break;
              case 9:
                r << ((neg)? "3/4": "3/4+");
                break;
              case 10:
                r << ((neg)? "5/6": "5/6+");
                break;
            }
            first = true;
            while (j < 3) {
              if ((*m)(i, j) != 0.)
                {
                  neg = (*m)(i, j) < 0.;
                  switch (j)
                    {
                      case 0:
                        r << ((neg)? "-x": (first? "x": "+x"));
                        break;
                     case 1:
                        r << ((neg)? "-y": (first? "y": "+y"));
                        break;
                     case 2:
                        r << ((neg)? "-z": (first? "z": "+z"));
                        break;
                    }
                  first = false;
                }
              j++;
            }
        }
      return r.str();
    }

