static FILE* hsm_mk_change_op_open(const char *id, CK_SLOT_ID slot_id,
                                   const char *mode)
{
    char hsm_mk_change_file[PATH_MAX];
    FILE *fp;

    if (slot_id != (CK_SLOT_ID)-1) {
        if (ock_snprintf(hsm_mk_change_file, PATH_MAX, "%s/%s-%lu",
                         OCK_HSM_MK_CHANGE_PATH, id, slot_id) != 0) {
            TRACE_ERROR("HSM_MK_CHANGE directory path buffer overflow\n");
            return NULL;
        }
    } else {
        if (ock_snprintf(hsm_mk_change_file, PATH_MAX, "%s/%s",
                         OCK_HSM_MK_CHANGE_PATH, id) != 0) {
            TRACE_ERROR("HSM_MK_CHANGE directory path buffer overflow\n");
            return NULL;
        }
    }

    TRACE_DEVEL("file to open: %s mode: %s\n", hsm_mk_change_file, mode);

    fp = fopen(hsm_mk_change_file, mode);
    if (fp == NULL) {
        TRACE_ERROR("%s fopen(%s, %s): %s\n", __func__,
                        hsm_mk_change_file, mode, strerror(errno));
    }

    return fp;
}

static FILE* hsm_mk_change_op_open(const char *id, CK_SLOT_ID slot_id,
                                   const char *mode)
{
    char hsm_mk_change_file[PATH_MAX];
    FILE *fp;

    if (slot_id != (CK_SLOT_ID)-1) {
        if (ock_snprintf(hsm_mk_change_file, PATH_MAX, "%s/%s-%lu",
                         OCK_HSM_MK_CHANGE_PATH, id, slot_id) != 0) {
            TRACE_ERROR("HSM_MK_CHANGE directory path buffer overflow\n");
            return NULL;
        }
    } else {
        if (ock_snprintf(hsm_mk_change_file, PATH_MAX, "%s/%s",
                         OCK_HSM_MK_CHANGE_PATH, id) != 0) {
            TRACE_ERROR("HSM_MK_CHANGE directory path buffer overflow\n");
            return NULL;
        }
    }

    TRACE_DEVEL("file to open: %s mode: %s\n", hsm_mk_change_file, mode);


    fp = fopen_nofollow(hsm_mk_change_file, mode);
    if (fp == NULL) {
        if (errno == ELOOP)
            TRACE_ERROR("Refusing to follow symlink: %s\n", hsm_mk_change_file);
        else
            TRACE_ERROR("%s fopen(%s, %s): %s\n", __func__,
                        hsm_mk_change_file, mode, strerror(errno));
    }

    return fp;
}

static int set_file_permissions(const char *fname, const struct group *group,
                                bool recursive)
{
    struct stat sb;
    struct passwd *pwd;
    int err, i, rc, mode;
    bool found = false;
    uid_t uid = (uid_t)-1;
    DIR *dir;
    struct dirent *entry;
    char ent[PATH_MAX];

    pr_verbose("Setting permissions for '%s' with group '%s'", fname,
               group->gr_name);

    if (stat(fname, &sb) != 0) {
        warnx("'%s' does not exist.", fname);
        return -1;
    }

    if (sb.st_uid != 0) {

        pwd = getpwuid(sb.st_uid);


        for (i = 0; pwd != NULL && group->gr_mem[i] != NULL; i++) {
            if (strcmp(group->gr_mem[i], pwd->pw_name) == 0) {
                found = true;
                break;
            }
        }

        if (!found)
            uid = 0; 
    }


    if (S_ISDIR(sb.st_mode))
        mode = S_IRUSR | S_IWUSR | S_IXUSR | S_IRGRP | S_IWGRP | S_IXGRP;
    else
        mode = S_IRUSR | S_IWUSR | S_IRGRP | S_IWGRP;
    if (chmod(fname, mode) != 0) {
        err = errno;
        warnx("Failed to set permissions on '%s': %s", fname, strerror(err));
        return -1;
    }


    if (chown(fname, uid, group->gr_gid) != 0) {
        err = errno;
        warnx("Failed to change the owner on '%s': %s", fname, strerror(err));
        return -1;
    }

    if (recursive && S_ISDIR(sb.st_mode)) {
        dir = opendir(fname);
        if (dir == NULL) {
            err = errno;
            warnx("Failed to open directory '%s': %s", fname, strerror(err));
            return -1;
        }


        rc = 0;
        while ((entry = readdir(dir)) != NULL) {
            if (strncmp(entry->d_name, ".", 1) == 0)
                continue;

            snprintf(ent, PATH_MAX, "%s/%s", fname, entry->d_name);
            rc = set_file_permissions(ent, group, recursive);
            if (rc != 0)
                break;
        }

        closedir(dir);

        if (rc != 0)
            return rc;
    }

    return 0;
}

