    }


    if (alg_len >= ber_rsaEncryptionLen) {
        if (memcmp(alg, ber_rsaEncryption, ber_rsaEncryptionLen) == 0) {
            *keytype = CKK_RSA;
            return CKR_OK;
        }
    }


    if (alg_len >= ber_idDSALen) {
        if (memcmp(alg, ber_idDSA, ber_idDSALen) == 0) {
            *keytype = CKK_DSA;
            return CKR_OK;
        }
    }


    if (alg_len >= der_AlgIdECBaseLen) {
        if (memcmp(alg, ber_idEC, ber_idECLen) == 0) {
            *keytype = CKK_EC;
            return CKR_OK;
        }
    }


    for (i = 0; i < NUMEC; i++) {
        if (der_ec_supported[i].curve_type == EDWARDS_CURVE &&
            alg_len >= der_ec_supported[i].data_size &&
            memcmp(alg, der_ec_supported[i].data,
                   der_ec_supported[i].data_size) == 0) {
            *keytype = CKK_EC_EDWARDS;
            return CKR_OK;
        }
    }


    for (i = 0; i < NUMEC; i++) {
        if (der_ec_supported[i].curve_type == MONTGOMERY_CURVE &&
            alg_len >= der_ec_supported[i].data_size &&
            memcmp(alg, der_ec_supported[i].data,
                   der_ec_supported[i].data_size) == 0) {
            *keytype = CKK_EC_MONTGOMERY;
            return CKR_OK;
        }
    }


    if (alg_len >= ber_idDHLen) {
        if (memcmp(alg, ber_idDH, ber_idDHLen) == 0) {
            *keytype = CKK_DH;
            return CKR_OK;
        }
    }


    for (i = 0; dilithium_oids[i].oid != NULL; i++) {
        if (alg_len == dilithium_oids[i].oid_len + ber_NULLLen &&
            memcmp(alg, dilithium_oids[i].oid,
                   dilithium_oids[i].oid_len) == 0 &&
            memcmp(alg + dilithium_oids[i].oid_len,
                   ber_NULL, ber_NULLLen) == 0) {
            *keytype = CKK_IBM_PQC_DILITHIUM;
            return CKR_OK;
        }
    }


    for (i = 0; kyber_oids[i].oid != NULL; i++) {
        if (alg_len == kyber_oids[i].oid_len + ber_NULLLen &&
            memcmp(alg, kyber_oids[i].oid, kyber_oids[i].oid_len) == 0 &&
            memcmp(alg + kyber_oids[i].oid_len, ber_NULL, ber_NULLLen) == 0) {
            *keytype = CKK_IBM_PQC_KYBER;
            return CKR_OK;
        }
    }


    for (i = 0; ml_dsa_oids[i].oid != NULL; i++) {
        if (alg_len == ml_dsa_oids[i].oid_len &&
            memcmp(alg, ml_dsa_oids[i].oid, ml_dsa_oids[i].oid_len) == 0) {
            *keytype = CKK_IBM_ML_DSA;
            return CKR_OK;
        }
    }


    for (i = 0; ml_kem_oids[i].oid != NULL; i++) {
        if (alg_len == ml_kem_oids[i].oid_len &&
            memcmp(alg, ml_kem_oids[i].oid, ml_kem_oids[i].oid_len) == 0) {
            *keytype = CKK_IBM_ML_KEM;
            return CKR_OK;
        }
    }

    TRACE_ERROR("%s\n", ock_err(ERR_TEMPLATE_INCOMPLETE));
    return CKR_TEMPLATE_INCOMPLETE;
}

