srs_error_t SrsHttpMessage::set_url(string url, bool allow_jsonp)
{
    srs_error_t err = srs_success;

    _url = url;


    std::string uri = _url;

    if (!srs_string_contains(uri, "://")) {


        std::string host = _header.get("Host");


        if (host.empty()) {
            host = srs_get_public_internet_address(true);
        }


        if (!host.empty() && !srs_string_starts_with(_url, "/")) {
            host += "/";
        }

        if (!host.empty()) {
            uri = "http://" + host + _url;
        }
    }

    if ((err = _uri->initialize(uri)) != srs_success) {
        return srs_error_wrap(err, "init uri %s", uri.c_str());
    }


    _ext = srs_path_filext(_uri->get_path());


    srs_parse_query_string(_uri->get_query(), _query);


    if (allow_jsonp) {
        if (!query_get("callback").empty()) {
            jsonp = true;
        }
        if (jsonp) {
            jsonp_method = query_get("method");
        }
    }

    return err;
}

srs_error_t SrsHttpMessage::set_url(string url, bool allow_jsonp)
{
    srs_error_t err = srs_success;

    _url = url;


    std::string uri = _url;

    if (!srs_string_contains(uri, "://")) {


        std::string host = _header.get("Host");


        if (host.empty()) {
            host = srs_get_public_internet_address(true);
        }


        if (!host.empty() && !srs_string_starts_with(_url, "/")) {
            host += "/";
        }

        if (!host.empty()) {
            uri = "http://" + host + _url;
        }
    }

    if ((err = _uri->initialize(uri)) != srs_success) {
        return srs_error_wrap(err, "init uri %s", uri.c_str());
    }


    _ext = srs_path_filext(_uri->get_path());


    srs_parse_query_string(_uri->get_query(), _query);


    if (allow_jsonp) {
        string callback= query_get("callback");
        jsonp = !callback.empty();

        if (jsonp) {
            jsonp_method = query_get("method");
        }

        if (!srs_is_valid_jsonp_callback(callback)) {
            return srs_error_new(ERROR_HTTP_JSONP, "invalid callback=%s", callback.c_str());
        }
    }

    return err;
}

void hexdump(msg_info msg_info, const char *mem, unsigned int len)
{
    unsigned int i, j;
    char str[10 + HEXDUMP_COLS * 4 + 2];
    int c = 0; 

    for(i = 0; i < len + ((len % HEXDUMP_COLS) ? (HEXDUMP_COLS - len % HEXDUMP_COLS) : 0); i++)
    {

        if(i % HEXDUMP_COLS == 0)
            c += sprintf(&str[c], "0x%06x: ", i);


        if(i < len)
            c += sprintf(&str[c], "%02x ", 0xFF & mem[i]);
        else 
            c+= sprintf(&str[c], "   ");


        if(i % HEXDUMP_COLS == (HEXDUMP_COLS - 1)) {
            for(j = i - (HEXDUMP_COLS - 1); j <= i; j++) {
                if(j >= len) 
                    str[c++] = ' ';
                else if(isprint(mem[j])) 
                    str[c++] = 0xFF & mem[j];
                else 
                    str[c++] = '.';
            }
            str[c++] = '\n';
            str[c++] = 0;
            print_message(msg_info, str);
            c = 0;
        }
    }
}

void hexdump(msg_info msg_info, const char *mem, unsigned int len)
{
    unsigned int i, j;
    char str[10 + HEXDUMP_COLS * 4 + 2];
    int c = 0; 

    for(i = 0; i < len + ((len % HEXDUMP_COLS) ? (HEXDUMP_COLS - len % HEXDUMP_COLS) : 0); i++)
    {

        if(i % HEXDUMP_COLS == 0)
            c += sprintf(&str[c], "0x%06x: ", i);


        if(i < len)
            c += sprintf(&str[c], "%02x ", 0xFF & mem[i]);
        else 
            c+= sprintf(&str[c], "   ");


        if(i % HEXDUMP_COLS == (HEXDUMP_COLS - 1)) {
            for(j = i - (HEXDUMP_COLS - 1); j <= i; j++) {
                if(j >= len) 
                    str[c++] = ' ';
                else if(isprint(mem[j])) 
                    str[c++] = 0xFF & mem[j];
                else 
                    str[c++] = '.';
            }
            str[c++] = '\n';
            str[c++] = 0;
            print_message(msg_info, "%s", str);
            c = 0;
        }
    }
}

