std::vector<std::uint8_t> decode_base64(const std::string &input)
{
    std::size_t padding_count = 0;
    auto in_end = input.data() + input.size();

    while (*--in_end == '=')
    {
        ++padding_count;
    }

    auto decoded_length = ((6 * input.size()) / 8) - padding_count;
    auto output = std::vector<std::uint8_t>(decoded_length);
    auto input_iterator = input.begin();
    auto output_iterator = output.begin();
    auto i = std::size_t(0);
    auto j = std::size_t(0);
    std::array<std::uint8_t, 3> a3{{0}};
    std::array<std::uint8_t, 4> a4{{0}};

    auto b64_lookup = [](std::uint8_t c) -> std::uint8_t {
        if (c >= 'A' && c <= 'Z') return c - 'A';
        if (c >= 'a' && c <= 'z') return c - 71;
        if (c >= '0' && c <= '9') return c + 4;
        if (c == '+') return 62;
        if (c == '/') return 63;
        return 255;
    };

    while (input_iterator != input.end())
    {
        if (*input_iterator == '=')
        {
            break;
        }

        a4[i++] = static_cast<std::uint8_t>(*(input_iterator++));

        if (i == 4)
        {
            for (i = 0; i < 4; i++)
            {
                a4[i] = b64_lookup(a4[i]);
            }

            a3[0] = static_cast<std::uint8_t>(a4[0] << 2)
                + static_cast<std::uint8_t>((a4[1] & 0x30) >> 4);
            a3[1] = static_cast<std::uint8_t>((a4[1] & 0xf) << 4)
                + static_cast<std::uint8_t>((a4[2] & 0x3c) >> 2);
            a3[2] = static_cast<std::uint8_t>((a4[2] & 0x3) << 6)
                + static_cast<std::uint8_t>(a4[3]);

            for (i = 0; i < 3; i++)
            {
                *output_iterator++ = a3[i];
            }

            i = 0;
        }
    }

    if (i != 0)
    {
        for (j = i; j < 4; j++)
        {
            a4[j] = 0;
        }

        for (j = 0; j < 4; j++)
        {
            a4[j] = b64_lookup(a4[j]);
        }

        a3[0] = static_cast<std::uint8_t>(a4[0] << 2)
            + static_cast<std::uint8_t>((a4[1] & 0x30) >> 4);
        a3[1] = static_cast<std::uint8_t>((a4[1] & 0xf) << 4)
            + static_cast<std::uint8_t>((a4[2] & 0x3c) >> 2);
        a3[2] = static_cast<std::uint8_t>((a4[2] & 0x3) << 6)
            + static_cast<std::uint8_t>(a4[3]);

        for (j = 0; j < i - 1; j++)
        {
            *output_iterator++ = a3[j];
        }
    }

    return output;
}

std::vector<std::uint8_t> decode_base64(const std::string &input)
{
    if (input.empty())
    {
        return {};
    }

    std::size_t padding_count = 0;
    auto in_end = input.data() + input.size();

    while (in_end > input.data() && *--in_end == '=')
    {
        ++padding_count;
    }

    auto raw_size = (6 * input.size()) / 8;

    auto decoded_length = (padding_count > raw_size) ? 0 : (raw_size - padding_count);

    std::vector<std::uint8_t> output;
    output.reserve(decoded_length);

    auto input_iterator = input.begin();
    auto i = std::size_t(0);
    auto j = std::size_t(0);
    std::array<std::uint8_t, 3> a3{{0}};
    std::array<std::uint8_t, 4> a4{{0}};

    auto b64_lookup = [](std::uint8_t c) -> std::uint8_t {
        if (c >= 'A' && c <= 'Z') return c - 'A';
        if (c >= 'a' && c <= 'z') return c - 71;
        if (c >= '0' && c <= '9') return c + 4;
        if (c == '+') return 62;
        if (c == '/') return 63;
        return 255;
    };

    while (input_iterator != input.end())
    {
        if (*input_iterator == '=')
        {
            break;
        }

        a4[i++] = static_cast<std::uint8_t>(*(input_iterator++));

        if (i == 4)
        {
            for (i = 0; i < 4; i++)
            {
                a4[i] = b64_lookup(a4[i]);
            }

            a3[0] = static_cast<std::uint8_t>(a4[0] << 2)
                + static_cast<std::uint8_t>((a4[1] & 0x30) >> 4);
            a3[1] = static_cast<std::uint8_t>((a4[1] & 0xf) << 4)
                + static_cast<std::uint8_t>((a4[2] & 0x3c) >> 2);
            a3[2] = static_cast<std::uint8_t>((a4[2] & 0x3) << 6)
                + static_cast<std::uint8_t>(a4[3]);

            for (i = 0; i < 3; i++)
            {
                output.push_back(a3[i]);
            }

            i = 0;
        }
    }

    if (i != 0)
    {
        for (j = i; j < 4; j++)
        {
            a4[j] = 0;
        }

        for (j = 0; j < 4; j++)
        {
            a4[j] = b64_lookup(a4[j]);
        }

        a3[0] = static_cast<std::uint8_t>(a4[0] << 2)
            + static_cast<std::uint8_t>((a4[1] & 0x30) >> 4);
        a3[1] = static_cast<std::uint8_t>((a4[1] & 0xf) << 4)
            + static_cast<std::uint8_t>((a4[2] & 0x3c) >> 2);
        a3[2] = static_cast<std::uint8_t>((a4[2] & 0x3) << 6)
            + static_cast<std::uint8_t>(a4[3]);

        for (j = 0; j < i - 1; j++)
        {
            output.push_back(a3[j]);
        }
    }

    return output;
}

DLL_EXPORT_XLSXIO xlsxioreadersheetlist xlsxioread_sheetlist_open (xlsxioreader handle)
{

  XML_Char* mainsheetfile = NULL;
  iterate_files_by_contenttype(handle->zip, xlsx_content_type, xlsxioread_find_main_sheet_file_callback, &mainsheetfile, NULL);
  if (!mainsheetfile)
    iterate_files_by_contenttype(handle->zip, xlsm_content_type, xlsxioread_find_main_sheet_file_callback, &mainsheetfile, NULL);
  if (!mainsheetfile)
    iterate_files_by_contenttype(handle->zip, xltx_content_type, xlsxioread_find_main_sheet_file_callback, &mainsheetfile, NULL);
  if (!mainsheetfile)
    iterate_files_by_contenttype(handle->zip, xltm_content_type, xlsxioread_find_main_sheet_file_callback, &mainsheetfile, NULL);
  if (!mainsheetfile)
    return NULL;

  xlsxioreadersheetlist result;
  if ((result = (xlsxioreadersheetlist)malloc(sizeof(struct xlsxio_read_sheetlist_struct))) == NULL)
    return NULL;
  result->handle = handle;
  result->sheetcallbackdata.xmlparser = NULL;
  result->sheetcallbackdata.callback = xlsxioread_list_sheets_resumable_callback;
  result->sheetcallbackdata.callbackdata = result;
  result->nextsheetname = NULL;
  if ((result->zipfile = XML_Char_openzip(handle->zip, mainsheetfile, 0)) != NULL) {
    result->xmlparser = expat_process_zip_file_suspendable(result->zipfile, main_sheet_list_expat_callback_element_start, NULL, NULL, &result->sheetcallbackdata);
  }

  free(mainsheetfile);
  return result;
}

