static int tcpm_pd_set(struct typec_port *p, struct usb_power_delivery *pd)
{
	struct tcpm_port *port = typec_get_drvdata(p);
	struct pd_data *data;
	int i, ret = 0;

	mutex_lock(&port->lock);

	if (port->selected_pd == pd)
		goto unlock;

	data = tcpm_find_pd_data(port, pd);
	if (IS_ERR(data)) {
		ret = PTR_ERR(data);
		goto unlock;
	}

	if (data->sink_desc.pdo[0]) {
		for (i = 0; i < PDO_MAX_OBJECTS && data->sink_desc.pdo[i]; i++)
			port->snk_pdo[i] = data->sink_desc.pdo[i];
		port->nr_snk_pdo = i + 1;
		port->operating_snk_mw = data->operating_snk_mw;
	}

	if (data->source_desc.pdo[0]) {
		for (i = 0; i < PDO_MAX_OBJECTS && data->source_desc.pdo[i]; i++)
			port->src_pdo[i] = data->source_desc.pdo[i];
		port->nr_src_pdo = i + 1;
	}

	switch (port->state) {
	case SRC_UNATTACHED:
	case SRC_ATTACH_WAIT:
	case SRC_TRYWAIT:
		tcpm_set_cc(port, tcpm_rp_cc(port));
		break;
	case SRC_SEND_CAPABILITIES:
	case SRC_SEND_CAPABILITIES_TIMEOUT:
	case SRC_NEGOTIATE_CAPABILITIES:
	case SRC_READY:
	case SRC_WAIT_NEW_CAPABILITIES:
		port->caps_count = 0;
		port->upcoming_state = SRC_SEND_CAPABILITIES;
		ret = tcpm_ams_start(port, POWER_NEGOTIATION);
		if (ret == -EAGAIN) {
			port->upcoming_state = INVALID_STATE;
			goto unlock;
		}
		break;
	case SNK_NEGOTIATE_CAPABILITIES:
	case SNK_NEGOTIATE_PPS_CAPABILITIES:
	case SNK_READY:
	case SNK_TRANSITION_SINK:
	case SNK_TRANSITION_SINK_VBUS:
		if (port->pps_data.active)
			port->upcoming_state = SNK_NEGOTIATE_PPS_CAPABILITIES;
		else if (port->pd_capable)
			port->upcoming_state = SNK_NEGOTIATE_CAPABILITIES;
		else
			break;

		port->update_sink_caps = true;

		ret = tcpm_ams_start(port, POWER_NEGOTIATION);
		if (ret == -EAGAIN) {
			port->upcoming_state = INVALID_STATE;
			goto unlock;
		}
		break;
	default:
		break;
	}

	port->port_source_caps = data->source_cap;
	port->port_sink_caps = data->sink_cap;
	typec_port_set_usb_power_delivery(p, NULL);
	port->selected_pd = pd;
	typec_port_set_usb_power_delivery(p, port->selected_pd);
unlock:
	mutex_unlock(&port->lock);
	return ret;
}

