	if (lt->hdmi_port->ops & DRM_BRIDGE_OP_HPD)
		drm_bridge_hpd_disable(lt->hdmi_port);

	drm_connector_unregister(&lt->connector);
	drm_connector_cleanup(&lt->connector);
