void arch_cpu_idle_dead(void)
{
	sched_preempt_enable_no_resched();





	this_cpu_disable_ftrace();

	if (smp_ops->cpu_offline_self)
		smp_ops->cpu_offline_self();


	start_secondary_resume();
}

