	}

	if (dic->cpages) {
		for (i = 0; i < dic->nr_cpages; i++) {
			if (!dic->cpages[i])
				continue;
			f2fs_compress_free_page(dic->cpages[i]);
		}
		page_array_free(sbi, dic->cpages, dic->nr_cpages);
	}

	page_array_free(sbi, dic->rpages, dic->nr_rpages);
	kmem_cache_free(dic_entry_slab, dic);
