static int sve_set_common(struct task_struct *target,
			  const struct user_regset *regset,
			  unsigned int pos, unsigned int count,
			  const void *kbuf, const void __user *ubuf,
			  enum vec_type type)
{
	int ret;
	struct user_sve_header header;
	unsigned int vq;
	unsigned long start, end;
	bool fpsimd;

	fpsimd_flush_task_state(target);


	if (count < sizeof(header))
		return -EINVAL;
	ret = user_regset_copyin(&pos, &count, &kbuf, &ubuf, &header,
				 0, sizeof(header));
	if (ret)
		return ret;






	fpsimd = (header.flags & SVE_PT_REGS_MASK) == SVE_PT_REGS_FPSIMD;
	if (fpsimd && type == ARM64_VEC_SME)
		return -EINVAL;






	if (header.vl) {




		if (!system_supports_sve() && type == ARM64_VEC_SVE)
			return -EINVAL;






		ret = vec_set_vector_length(target, type, header.vl,
					    ((unsigned long)header.flags & ~SVE_PT_REGS_MASK) << 16);
		if (ret)
			return ret;
	} else {

		if (system_supports_sve())
			return -EINVAL;





		if (header.flags != SVE_PT_REGS_FPSIMD)
			return -EINVAL;
	}


	if (type == ARM64_VEC_SME) {
		sme_alloc(target, false);
		if (!target->thread.sme_state)
			return -ENOMEM;
	}


	if (!fpsimd) {
		sve_alloc(target, true);
		if (!target->thread.sve_state)
			return -ENOMEM;
	}






	vq = sve_vq_from_vl(task_get_vl(target, type));


	if (system_supports_sme()) {
		switch (type) {
		case ARM64_VEC_SVE:
			target->thread.svcr &= ~SVCR_SM_MASK;
			set_tsk_thread_flag(target, TIF_SVE);
			break;
		case ARM64_VEC_SME:
			target->thread.svcr |= SVCR_SM_MASK;
			set_tsk_thread_flag(target, TIF_SME);
			break;
		default:
			WARN_ON_ONCE(1);
			return -EINVAL;
		}
	}


	memset(&current->thread.uw.fpsimd_state, 0,
	       sizeof(current->thread.uw.fpsimd_state));



	BUILD_BUG_ON(SVE_PT_FPSIMD_OFFSET != sizeof(header));
	if (fpsimd) {
		clear_tsk_thread_flag(target, TIF_SVE);
		target->thread.fp_type = FP_STATE_FPSIMD;
		ret = __fpr_set(target, regset, pos, count, kbuf, ubuf,
				SVE_PT_FPSIMD_OFFSET);
		return ret;
	}



	target->thread.fp_type = FP_STATE_SVE;






	if (count && vq != sve_vq_from_vl(header.vl))
		return -EIO;

	BUILD_BUG_ON(SVE_PT_SVE_OFFSET != sizeof(header));
	start = SVE_PT_SVE_OFFSET;
	end = SVE_PT_SVE_FFR_OFFSET(vq) + SVE_PT_SVE_FFR_SIZE(vq);
	ret = user_regset_copyin(&pos, &count, &kbuf, &ubuf,
				 target->thread.sve_state,
				 start, end);
	if (ret)
		return ret;

	start = end;
	end = SVE_PT_SVE_FPSR_OFFSET(vq);
	user_regset_copyin_ignore(&pos, &count, &kbuf, &ubuf, start, end);





	start = end;
	end = SVE_PT_SVE_FPCR_OFFSET(vq) + SVE_PT_SVE_FPCR_SIZE;
	ret = user_regset_copyin(&pos, &count, &kbuf, &ubuf,
				 &target->thread.uw.fpsimd_state.fpsr,
				 start, end);

	return ret;
}

