void __target_init_cmd(
	struct se_cmd *cmd,
	const struct target_core_fabric_ops *tfo,
	struct se_session *se_sess,
	u32 data_length,
	int data_direction,
	int task_attr,
	unsigned char *sense_buffer, u64 unpacked_lun)
{
	INIT_LIST_HEAD(&cmd->se_delayed_node);
