	HLIST_HEAD(del_list);
	int i;
	int j;

	clear_bit(MLX5E_ARFS_STATE_ENABLED, &arfs->state);

	spin_lock_bh(&arfs->arfs_lock);
	mlx5e_for_each_arfs_rule(rule, htmp, arfs->arfs_tables, i, j) {
		hlist_del_init(&rule->hlist);
