}

static irqreturn_t mv88e6xxx_g1_atu_prob_irq_thread_fn(int irq, void *dev_id)
{
	struct mv88e6xxx_chip *chip = dev_id;
	struct mv88e6xxx_atu_entry entry;
	int err, spid;
	u16 val, fid;

	mv88e6xxx_reg_lock(chip);

	err = mv88e6xxx_g1_read_atu_violation(chip);
	if (err)
		goto out_unlock;

	err = mv88e6xxx_g1_read(chip, MV88E6XXX_G1_ATU_OP, &val);
	if (err)
		goto out_unlock;

	err = mv88e6xxx_g1_atu_fid_read(chip, &fid);
	if (err)
		goto out_unlock;

	err = mv88e6xxx_g1_atu_data_read(chip, &entry);
	if (err)
		goto out_unlock;

	err = mv88e6xxx_g1_atu_mac_read(chip, &entry);
	if (err)
		goto out_unlock;

	mv88e6xxx_reg_unlock(chip);

	spid = entry.state;

	if (val & MV88E6XXX_G1_ATU_OP_MEMBER_VIOLATION) {
		trace_mv88e6xxx_atu_member_violation(chip->dev, spid,
						     entry.portvec, entry.mac,
						     fid);
		chip->ports[spid].atu_member_violation++;
	}

	if (val & MV88E6XXX_G1_ATU_OP_MISS_VIOLATION) {
		trace_mv88e6xxx_atu_miss_violation(chip->dev, spid,
						   entry.portvec, entry.mac,
						   fid);
		chip->ports[spid].atu_miss_violation++;

		if (fid != MV88E6XXX_FID_STANDALONE && chip->ports[spid].mab) {
			err = mv88e6xxx_handle_miss_violation(chip, spid,
							      &entry, fid);
			if (err)
				goto out;
		}
	}

	if (val & MV88E6XXX_G1_ATU_OP_FULL_VIOLATION) {
		trace_mv88e6xxx_atu_full_violation(chip->dev, spid,
						   entry.portvec, entry.mac,
						   fid);
		chip->ports[spid].atu_full_violation++;
	}

	return IRQ_HANDLED;

out_unlock:
	mv88e6xxx_reg_unlock(chip);

out:
	dev_err(chip->dev, "ATU problem: error %d while handling interrupt\n",
		err);
	return IRQ_HANDLED;
}

